export const NS='http://www.w3.org/2000/svg';
export function svgEl(tag,attrs={}){const el=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,String(v));return el;}
export const serialize=root=>new XMLSerializer().serializeToString(root);
export function drawables(root){return [...root.querySelectorAll('*')].filter(el=>/^(path|rect|circle|ellipse|line|polyline|polygon|use)$/.test(el.localName)&&!el.closest('defs,clipPath,mask,symbol'));}
const allowed=new Set(['svg','g','path','rect','circle','ellipse','line','polyline','polygon','defs','clipPath','mask','linearGradient','radialGradient','stop','use','symbol','title','desc']);
const attrs=new Set(['id','d','x','y','x1','y1','x2','y2','cx','cy','r','rx','ry','fx','fy','fr','width','height','viewBox','preserveAspectRatio','points','transform','fill','stroke','stroke-width','stroke-linecap','stroke-linejoin','stroke-miterlimit','stroke-dasharray','stroke-dashoffset','fill-rule','clip-rule','clip-path','clipPathUnits','opacity','fill-opacity','stroke-opacity','mask','mask-type','maskUnits','maskContentUnits','gradientUnits','gradientTransform','spreadMethod','offset','stop-color','stop-opacity','href','xlink:href','xmlns','xmlns:xlink','style','vector-effect','display','visibility','color']);
const css=new Set(['fill','stroke','stroke-width','stroke-linecap','stroke-linejoin','stroke-miterlimit','stroke-dasharray','stroke-dashoffset','fill-rule','clip-rule','clip-path','mask','mask-type','opacity','fill-opacity','stroke-opacity','stop-color','stop-opacity','display','visibility','color','vector-effect']);
function localResources(value){if(/\\|javascript:|https?:|data:|@import|expression\s*\(/i.test(value))return false;for(const match of value.matchAll(/url\s*\(([^)]*)\)/gi)){const ref=match[1].trim().replace(/^(['"])(.*)\1$/,'$2');if(!/^#[\w:.-]+$/.test(ref))return false;}return (value.match(/url\s*\(/gi)||[]).length===[...value.matchAll(/url\s*\(([^)]*)\)/gi)].length;}
export function sanitize(text){if(typeof text!=='string'||text.length>1000000)throw new Error('Please use an SVG smaller than 1 MB.');const doc=new DOMParser().parseFromString(text,'image/svg+xml'),root=doc.documentElement;if(doc.querySelector('parsererror')||root.localName!=='svg'||root.namespaceURI!==NS)throw new Error('This file is not a valid SVG.');if(doc.querySelector('text'))throw new Error('Convert text to outlines, then upload the SVG again.');if(doc.querySelector('image,filter'))throw new Error('Export vector paths without embedded images or filters.');if(doc.querySelector('style'))throw new Error('This SVG uses a style sheet. Export SVG with presentation attributes or inline styles.');
const all=[root,...root.querySelectorAll('*')],ids=new Set();if(all.length>4000)throw new Error('Simplify this SVG to fewer than 4,000 elements.');for(const el of all){if(!allowed.has(el.localName)||el.namespaceURI!==NS){el.remove();continue;}for(const a of [...el.attributes]){const value=a.value.trim();if(a.name==='xmlns'||a.name==='xmlns:xlink')continue;if(!attrs.has(a.name)){if(a.name==='filter')throw new Error('Export the SVG without filters first.');el.removeAttribute(a.name);continue;}if(a.name.includes('href')&&!/^#[\w:.-]+$/.test(value))throw new Error('Use an SVG with local vector paths, without external references.');if(!localResources(value))throw new Error('External resources are not supported. Embed styles and vector shapes in the SVG.');if(a.name==='style'){const declarations=[];for(const declaration of value.split(';')){if(!declaration.trim())continue;const at=declaration.indexOf(':'),key=declaration.slice(0,at).trim(),v=declaration.slice(at+1).trim();if(at<0||!css.has(key)||!localResources(v)||/var\(|calc\(/i.test(v))throw new Error('Export the SVG with presentation attributes; an inline style is unsupported.');declarations.push(key+':'+v);}el.setAttribute('style',declarations.join(';'));}}const id=el.getAttribute('id');if(id){if(ids.has(id))throw new Error('This SVG contains duplicate element IDs. Re-export it with unique IDs.');ids.add(id);}}
root.setAttribute('xmlns',NS);let view=(root.getAttribute('viewBox')||'').trim().split(/[ ,]+/).map(Number);if(view.length!==4||view.some(v=>!Number.isFinite(v))||view[2]<=0||view[3]<=0){const w=parseFloat(root.getAttribute('width')),h=parseFloat(root.getAttribute('height'));if(!(w>0&&h>0))throw new Error('The SVG needs a valid viewBox or dimensions.');view=[0,0,w,h];root.setAttribute('viewBox',view.join(' '));}if(view.some(v=>Math.abs(v)>1e7))throw new Error('The SVG coordinate range is too large. Re-export at a normal artboard size.');return {root,view};}
export function namespaceSVG(source,prefix,view){const root=typeof source==='string'?new DOMParser().parseFromString(source,'image/svg+xml').documentElement:source.cloneNode(true),els=[root,...root.querySelectorAll('*')],map=new Map();for(const el of els){if(el.id){map.set(el.id,prefix+'-'+map.size);}}
for(const el of els){for(const a of [...el.attributes]){let value=a.value;if(a.name==='id')value=map.get(value);else if(a.name.includes('href')&&value.startsWith('#'))value='#'+(map.get(value.slice(1))||prefix+'-missing');else value=value.replace(/url\(\s*['"]?#([\w:.-]+)['"]?\s*\)/gi,(_,id)=>'url(#'+(map.get(id)||prefix+'-missing')+')');el.setAttribute(a.name,value);}}
if(view){root.setAttribute('x',view[0]);root.setAttribute('y',view[1]);root.setAttribute('width',view[2]);root.setAttribute('height',view[3]);}return root;}
export function isolate(root,index){const copy=root.cloneNode(true);drawables(copy).forEach((el,i)=>{if(i!==index)el.remove();});return copy;}
export function measureParents(root,view){const host=document.createElement('div');host.style.cssText='position:fixed;left:-100000px;top:0;opacity:0;pointer-events:none;';const copy=namespaceSVG(root,'measure');copy.setAttribute('width',view[2]);copy.setAttribute('height',view[3]);host.append(copy);document.body.append(host);try{const rootCTM=copy.getCTM();return drawables(copy).map(el=>{const parentCTM=el.parentElement.getCTM?.()||rootCTM,m=rootCTM.inverse().multiply(parentCTM).inverse();if(![m.a,m.b,m.c,m.d,m.e,m.f].every(Number.isFinite))throw new Error('Unsupported SVG transform. Flatten transforms and try again.');return [m.a,m.b,m.c,m.d,m.e,m.f];});}finally{host.remove();}}
export function maskBounds(view,m){const [x,y,w,h]=view,pts=[[x-w,y-h],[x+2*w,y-h],[x-w,y+2*h],[x+2*w,y+2*h]].map(([a,b])=>[m[0]*a+m[2]*b+m[4],m[1]*a+m[3]*b+m[5]]);const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);return {x:Math.min(...xs),y:Math.min(...ys),width:Math.max(...xs)-Math.min(...xs),height:Math.max(...ys)-Math.min(...ys)};}

function paintOf(el){for(let n=el;n&&n.nodeType===1;n=n.parentElement){const style=(n.getAttribute('style')||'').match(/(?:^|;)\s*fill\s*:\s*([^;]+)/i),value=(style?style[1]:n.getAttribute('fill'))?.trim().toLowerCase();if(value&&value!=='inherit')return value;}return '';}
function isWhite(paint){if(paint==='white')return true;let m=paint.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/);if(m){const h=m[1].length===3?[...m[1]].map(c=>c+c).join(''):m[1];return [0,2,4].every(i=>parseInt(h.slice(i,i+2),16)>=248);}m=paint.match(/^rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)/);return !!m&&[m[1],m[2],m[3]].every(v=>Number(v)>=248);}
// Figma exports often include white backgrounds or knock-out shapes that should not be traced or animated.
export function removeWhiteFills(root){let removed=0;for(const el of drawables(root))if(isWhite(paintOf(el))){el.remove();removed++;}return removed;}
